def gen(rng):
    def make_val(pool):
        r = rng.random()
        if r < 0.35:
            return str(rng.choice(pool['nums']))
        if r < 0.65:
            return '"%s"' % rng.choice(pool['strs'])
        if r < 0.75:
            return rng.choice(['true', 'false'])
        if r < 0.85:
            return 'null'
        return '{}'
    def make(nvals, maxdepth, popen, pclose, pool):
        out = ['[']
        need = [False]
        depth = 1
        for _ in range(nvals):
            while rng.random() < popen and depth < maxdepth:
                if need[-1]:
                    out.append(',')
                out.append('[')
                need[-1] = True
                need.append(False)
                depth += 1
            while depth > 1 and rng.random() < pclose:
                out.append(']')
                need.pop()
                depth -= 1
            if need[-1]:
                out.append(',')
            out.append(make_val(pool))
            need[-1] = True
        while depth > 0:
            out.append(']')
            depth -= 1
        return ''.join(out)
    small = {'nums': list(range(-3, 6)), 'strs': ['a', 'b', 'ab', '1', '3', 'x9', 'true', 'null']}
    tests = [
        '[]',
        '[[],[[]]]',
        '[[[[]]]]',
        '[1]',
        '[{}]',
        '[null,null,[null]]',
        '[1,"a",[true,["b",null],[{},null]],1]',
        '[3,"3",-1,[3,[3,"3"]],false,true,false]',
        '["true","null","false",true,null,false]',
        '[0,1000000000,-1000000000,[10,2,1,-10,-2]]',
    ]
    for nv in (1, 2, 3, 5, 8, 10, 14):
        for _ in range(4):
            tests.append(make(nv, 6, 0.4, 0.4, small))
    # large: many distinct numbers and strings
    def big_pool(nnums, nstrs):
        al = 'abcdefghijklmnopqrstuvwxyz0123456789'
        strs = set()
        while len(strs) < nstrs:
            strs.add(''.join(rng.choice(al) for _ in range(rng.randint(1, 8))))
        return {'nums': [rng.randint(-10**9, 10**9) for _ in range(nnums)], 'strs': sorted(strs)}
    tests.append(make(200000, 50, 0.5, 0.5, big_pool(30000, 30000)))
    tests.append(make(200000, 8, 0.3, 0.6, small))
    tests.append(make(200000, 3000, 0.9, 0.1, big_pool(100, 100)))
    # exactly depth 5000
    tests.append('[' * 4999 + '[1,"a",null,{},true,1]' + ']' * 4999)
    tests.append('[' * 5000 + ']' * 5000)
    return tests
